async function ajax(handler,data={},opts={}){const visibleContext=(await dataContext()).context;if(visibleContext)browserContext=visibleContext;if(opts.context===undefined)opts={...opts,context:browserContext};const res=await page.evaluate(async({handler,data,opts})=>{const headers={'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest','X-AJAX-HANDLER':handler};if(opts.context!==null)headers['X-Workspace-Context']=opts.context??document.querySelector('form[data-workspace-context]')?.dataset.workspaceContext??'';const body=new URLSearchParams(data);if(opts.csrf!==false)body.set('_token',opts.csrfValue??document.querySelector('input[name="_token"]')?.value??'');else body.delete('_token');const r=await fetch(opts.url||location.href,{method:'POST',headers,body});return {status:r.status,body:await r.text()};},{handler,data,opts});note(handler,{status:res.status});return res;}
async function reject(handler,data,status=409,opts={}){const before=db();const r=await ajax(handler,data,opts);assert.ok([].concat(status).includes(r.status),`${handler}: expected ${status}, got ${r.status}`);assert.ok(!/SQLSTATE\[|Stack trace:/.test(r.body),'Unsafe response details');unchanged(before);return r;}
