async function runCase(id,fn) {
 const c=report.cases[Number(id)-1];
 if(c.disposition==='pass'&&!options.rerun&&!options.supplement){assert.equal(c.fixtureHelperSha256,fixtureHelperSha256,'Changed helper requires rerun');assert.equal(c.runnerSha256,runnerSha256,'Changed runner requires rerun');assert.equal(c.appManifestSha256,appManifestSha256,'Changed application requires rerun');return;}
 await assertSource();
 current={...c,error:undefined,pendingSegment:undefined,findings:options.supplement?(c.findings??[]):[],attempts:[...(c.attempts??[]),...(c.started?[{started:c.started,finished:c.finished,disposition:c.disposition,error:c.error,findings:c.findings,checks:c.checks,createdRows:c.createdRows,reconciliation:c.reconciliation,runnerSha256:c.runnerSha256,fixtureHelperSha256:c.fixtureHelperSha256,runtimeExceptions:c.runtimeExceptions,attemptId:c.attemptId,appManifestSha256:c.appManifestSha256}]:[])],checks:options.supplement?[...(c.checks??[]),{label:'Additional approved variants'}]:[],started:new Date().toISOString(),disposition:'running'};
 report.cases[Number(id)-1]=current;
 current.attemptId=crypto.randomUUID();current.appManifestSha256=appManifestSha256;
 current.runnerSha256=runnerSha256;
 current.fixtureHelperSha256=fixtureHelperSha256;
 await persist();await browserEvents();runtimeEvents=[];let beforeIds={};
 try {
  beforeIds=Object.fromEntries(Object.entries(db().tables).map(([t,rs])=>[t,new Set(rs.map(r=>r.id).filter(Boolean))]));
  await fn();current.disposition=current.pendingSegment?'blocked':current.findings?.length?'fail':'pass';if(current.pendingSegment)current.error=current.pendingSegment;
 } catch(e) {
  current.disposition=e.blocked?'blocked':'fail';current.error=redact(e.message).slice(0,700);await shot(id+'-failure').catch(()=>{});
 } finally {
  await page.cdp('Network.emulateNetworkConditions',{offline:false,latency:0,downloadThroughput:-1,uploadThroughput:-1}).catch(()=>{});
  await page.cdp('Fetch.disable').catch(()=>{});await page.cdp('Emulation.setDeviceMetricsOverride',desktop);
  try {
   const end=db();
   current.createdRows=Object.fromEntries(Object.entries(end.tables).map(([t,rs])=>[t,rs.filter(r=>r.id&&!beforeIds[t]?.has(r.id)).map(r=>r.id)]).filter(([,ids])=>ids.length));
   current.reconciliation={errors:end.reconciliation_errors,tables:Object.fromEntries(Object.entries(end.tables).map(([t,rs])=>[t,rs.length]))};
  } catch(e) {
   current.disposition='blocked';current.reconciliation={error:redact(e.message)};report.haltWrites=true;
  }
  await browserEvents();current.runtimeExceptions=runtimeEvents.map(e=>({description:redact(e.params?.exceptionDetails?.exception?.description??e.params?.exceptionDetails?.text??'Unknown runtime exception')}));
  if(current.runtimeExceptions.length&&current.disposition==='pass'){current.disposition='fail';current.error='Unexpected JavaScript runtime exceptions';}
  await assertSource();current.finished=new Date().toISOString();await persist();console.log(current.id,current.disposition,current.error??'');current=null;
 }
}
