async function httpActor(alias){
 const jar='/private/tmp/wesria-unhappy-'+fixture.nonce+'-'+alias+'.cookies';await fs.writeFile(jar,'',{mode:0o600});
 const client={csrf:'',context:'',async request(path,handler,data={}){
  const args=['-k','-sS','--max-time','20','-b',jar,'-c',jar,'-w','\n__STATUS__%{http_code}'];
  let input;
  if(handler){args.push('-H','X-Requested-With: XMLHttpRequest','-H','X-AJAX-HANDLER: '+handler,'-H','Content-Type: application/x-www-form-urlencoded','-H','X-Workspace-Context: '+client.context,'--data-binary','@-');input=new URLSearchParams({...data,_token:client.csrf}).toString();}
  args.push(base+path);
  const result=await new Promise((resolve,reject)=>{const p=cp.spawn('curl',args);let out='',err='';p.stdout.on('data',x=>out+=x);p.stderr.on('data',x=>err+=x);p.on('error',reject);p.on('close',code=>code?reject(new Error('Native HTTP actor transport failed '+code)):resolve(out));p.stdin.end(input);});
  const at=result.lastIndexOf('\n__STATUS__');const body=result.slice(0,at),status=Number(result.slice(at+11));
  if(!handler){client.csrf=body.match(/name="_token"[^>]*value="([^"]+)"/)?.[1]??client.csrf;client.context=body.match(/data-workspace-context="([^"]+)"/)?.[1]??client.context;}
  if(handler){let message;try{const j=JSON.parse(body);message=j.X_OCTOBER_ERROR_MESSAGE??j.message??j.error;}catch{if(status>=400)message=body.replace(/<script[\s\S]*?<\/script>/g,'').replace(/<style[\s\S]*?<\/style>/g,'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,350);}note('Background native request',{handler,status,message});}return{body,status};
 }};
 await client.request('/auth');assert.ok(client.csrf,'HTTP actor CSRF obtained');
 assert.equal((await client.request('/auth','identity::onLogin',{email:fixture[alias].email,password:fixture[alias].password??fixture.password})).status,200,'HTTP actor login');
 await client.request('/workspaces');assert.ok(client.context,'HTTP actor workspace context obtained');
 assert.equal((await client.request('/workspaces','workspaces::onSwitch',{company_id:fixture[alias].company_id,branch_id:fixture[alias].branch_id})).status,200);
 await client.request('/workspaces');
 const browser=await page.cdp('Network.getCookies',{urls:[base]});const cookieText=await fs.readFile(jar,'utf8');
 const cookies=cookieText.split('\n').filter(l=>l&&!l.startsWith('# ')&&l.split('\t').length===7).map(l=>l.split('\t'));
 const shared=browser.cookies.filter(c=>/session/i.test(c.name)).some(c=>cookies.some(r=>r[5]===c.name&&r[6]===c.value));assert.equal(shared,false,'Actor must not reuse browser session');note('Independent native HTTP actor session verified',{actor:alias});
 return client;
}
