function operation(table,id,extra={}){const r=record(db(),table,id);assert.ok(r,'Operation target exists');return{id,version:r.version,operation_key:crypto.randomUUID(),...extra};}
async function setActive(kind,id,active){await go('/catalogue/'+kind+'?edit='+id);const d=await form('#catalogue-form');const r=await ajax('catalogue::onSetActive',{kind,id,version:d.version,is_active:active?'1':'0'});assert.equal(r.status,200);}
async function approvePO(id){await go('/purchasing?id='+id);await action('purchasing::onApprove');}
async function approveSO(id){await go('/sales?id='+id);await action('sales::onApprove');}
