async function pdf(name){const result=await page.cdp('Page.printToPDF',{printBackground:true,preferCSSPageSize:true});const bytes=Buffer.from(result.data,'base64');assert.equal(bytes.subarray(0,5).toString(),'%PDF-');const file=output+'/'+name+'-'+Date.now()+'.pdf';await fs.writeFile(file,bytes);report.artifacts.push({case:current.id,attemptId:current.attemptId,runnerSha256,appManifestSha256,file,sha256:hash(bytes),inspected:false});return file;}
